// The API contract's types: the request bodies and replies of the routes waypoint/server/contract.py covers.
// Generated by tools/api_contract.py from docs/openapi.json (`make api-contract`); don't edit by hand.
// lib/contract.ts's apiCall() types a call by its route, as Endpoints names it: apiCall<"GET /api/budget">(address).

/** Settings → AI. A field left out stays as it was; `openrouter_key: ""` forgets the saved key. */
export interface AiBody {
  mode: "off" | "local" | "openrouter";
  ollama_url?: string;
  ollama_model?: string;
  openrouter_model?: string;
  openrouter_key?: string;
}

export interface AiSettings {
  mode: "off" | "local" | "openrouter";
  ollama_url: string;
  ollama_model: string;
  openrouter_model: string;
  key: "env" | "saved" | null;
}

/** The booking's fields the AI read, as the Add by hand form has them. A flight has no zones: its airports give them. */
export interface AiSuggestion {
  kind: "flight" | "hotel" | "car" | "train";
  origin: string;
  start_local: string;
  end_local: string;
  provider?: string;
  confirmation?: string;
  destination?: string;
  start_zone?: string;
  end_zone?: string;
}

export interface Airport {
  code: string;
  name: string;
  city: string;
  country: string;
  zone: string;
}

export interface BackupContents {
  created: string | null;
  source: string | null;
  counts: Record<string, number>;
  current: Record<string, number>;
  database: "sqlite" | "postgres";
}

/** Guests the signed-in member may be (their name matches, and they have no trips yet), for "Are you one of these?". */
export interface ClaimSuggestions {
  guests: Person[];
}

/** A browser's push subscription (`PushSubscription.toJSON()`). */
export interface DeviceBody {
  endpoint: string;
  p256dh: string;
  auth: string;
}

export interface Disconnected {
  ok: boolean;
  revoked: boolean;
}

export interface DistanceUnit {
  distance_unit: "mi" | "km";
}

export interface DistanceUnitBody {
  distance_unit: "mi" | "km";
}

export interface FeedMade {
  url: string;
}

/**
 * A flight's live status, shown beside its booked times (the booking is never changed). Times are `2026-03-01T22:15`
 * wall-clock times at the airports, in their zones (`dep_zone`, `arr_zone`), never converted.
 */
export interface FlightStatus {
  segment_id: number;
  state: "scheduled" | "delayed" | "departed" | "landed" | "cancelled" | "diverted";
  origin: string | null;
  destination: string | null;
  dep_scheduled: string | null;
  dep_estimated: string | null;
  dep_actual: string | null;
  dep_zone: string;
  dep_terminal: string | null;
  dep_gate: string | null;
  arr_scheduled: string | null;
  arr_estimated: string | null;
  arr_actual: string | null;
  arr_zone: string;
  arr_terminal: string | null;
  arr_gate: string | null;
  delay_minutes: number | null;
  fetched_at: string;
}

export interface FlightStatusList {
  enabled: boolean;
  month: string;
  used: number;
  limit: number;
  paused: FlightStatusPause | null;
  statuses: FlightStatus[];
}

export interface FlightStatusPause {
  until: string;
  reason: "limit" | "rate" | "key";
}

export interface ImportBody {
  flights: ImportFlight[];
  person_ids?: number[];
}

/** A flight to save, as the preview showed it: the web app sends back only the rows being saved, never the file. */
export interface ImportFlight {
  day: string;
  origin: string;
  destination: string;
  flight_number?: string | null;
  airline?: string | null;
  start_local?: string | null;
  end_local?: string | null;
  seat?: string | null;
  cabin?: string | null;
}

export interface ImportPreview {
  format: string;
  me: number | null;
  rows: ImportRow[];
}

/**
 * One row of the uploaded file as a flight, for the preview: new, already in Waypoint, or one that can't be read (with
 * why). Times are local wall-clock times at the airports; both are null when the file gave none.
 */
export interface ImportRow {
  line: number;
  status: "new" | "exists" | "unreadable";
  reason: string | null;
  day: string | null;
  origin: string | null;
  destination: string | null;
  flight_number: string | null;
  airline: string | null;
  start_local: string | null;
  end_local: string | null;
  seat: string | null;
  cabin: string | null;
}

export interface Imported {
  added: number;
  existing: number;
}

/**
 * Settings → Logos. A field left out stays as it was; `clear` forgets the publishable key (and so the secret one too),
 * `clear_secret` forgets only the secret key.
 */
export interface LogoDevBody {
  token?: string;
  secret?: string;
  clear?: boolean;
  clear_secret?: boolean;
}

export interface LogoDevFetch {
  started: boolean;
}

export interface LogoDevStatus {
  configured: boolean;
  searchable: boolean;
  with_logo: number;
  unknown: number;
  waiting: number;
  last_error: string | null;
}

/** A membership, to save or to change. `number` is needed to save one; left out when changing, the saved one is kept. */
export interface LoyaltyBody {
  person_id: number;
  kind: string;
  program: string;
  number?: string | null;
  tier?: string | null;
  expiry?: string | null;
  notes?: string | null;
}

/** A person with two different numbers for one program (both are kept); People says so. */
export interface LoyaltyConflict {
  person_id: number;
  kind: string;
  program: string;
}

/** One membership. The number comes only masked (its last four characters); `POST /api/loyalty/{id}/reveal` gives it. */
export interface LoyaltyEntry {
  id: number;
  person_id: number;
  kind: string;
  program: string;
  masked: string;
  readable: boolean;
  tier: string | null;
  expiry: string | null;
  notes: string | null;
}

export interface LoyaltyList {
  loyalty: LoyaltyEntry[];
  conflicts: LoyaltyConflict[];
  programs: Record<string, string[]>;
}

export interface Mailbox {
  id: number;
  address: string;
  status: "connected" | "reconnect" | "error";
  last_error: string | null;
  last_scan: string | null;
  scan_error: string | null;
  scanning: boolean;
  scan_notice: string | null;
}

export interface MailboxList {
  configured: boolean;
  mailboxes: Mailbox[];
}

export interface Matched {
  ok: boolean;
  matched: number;
}

/** An assistant connected with OAuth: one approval, ended by Disconnect or when its approver can no longer sign in. */
export interface McpConnection {
  id: number;
  client: string | null;
  who: string | null;
  scope: string[];
  created: string | null;
  last_used: string | null;
}

export interface McpSettings {
  allow_writes: boolean;
  oauth: boolean;
  url: string | null;
  reason: string | null;
  connections: McpConnection[];
}

export interface McpWritesBody {
  allow: boolean;
}

export interface MergeBody {
  merge: number;
}

export interface Ok {
  ok: boolean;
}

export interface People {
  people: Person[];
}

/** Someone who travels: a household member (`member`, linked to their sign-in) or a guest with no login. */
export interface Person {
  id: number;
  display_name: string;
  first_name: string | null;
  legal_name: string | null;
  aliases: string[];
  member: boolean;
  links: PersonLink[];
}

/**
 * A person's names, to add a guest or to change anyone's (a member's link to their login can't be changed). Changing
 * replaces all of them, so send every name to keep: one left out is cleared.
 */
export interface PersonBody {
  display_name: string;
  first_name?: string | null;
  legal_name?: string | null;
  aliases?: string[];
}

/** A guest a member claimed: their name, the member who claimed it and the day (YYYY-MM-DD). */
export interface PersonLink {
  guest: string;
  by: string;
  on: string;
}

/** A cruise's port of call. Its times are local wall-clock times at the port, in its `zone`. */
export interface Port {
  name: string;
  zone: string;
  arrive_local: string | null;
  depart_local: string | null;
}

/**
 * A review item's message as plain text, fetched from Gmail when asked and shown to its mailbox's owner alone; Waypoint keeps
 * none of it.
 */
export interface Preview {
  text: string;
  truncated: boolean;
}

/** A browser or phone that gets this member's notifications. */
export interface ReminderDevice {
  id: number;
  service: string;
  created: number;
}

/** The signed-in member's own: which reminders they get, their devices, and whether they have a calendar feed. */
export interface Reminders {
  public_key: string;
  check_in: boolean;
  day_of: boolean;
  devices: ReminderDevice[];
  feed: boolean;
}

export interface RemindersBody {
  check_in: boolean;
  day_of: boolean;
}

export interface Restored {
  ok: boolean;
  created: string | null;
  source: string | null;
  counts: Record<string, number>;
  safety_copy: string | null;
  unreadable_secrets: string[];
}

export interface Revealed {
  number: string;
}

export interface Review {
  items: ReviewItem[];
  who: WhoIsThis[];
  ai: boolean;
}

/**
 * One message Waypoint couldn't read, for the member whose mailbox it is. Never its subject or text: only who it
 * came from and its day (Open in Gmail shows the message).
 */
export interface ReviewItem {
  id: number;
  address: string;
  sender_domain: string;
  received: string | null;
  reason: "no_markup" | "incomplete" | "broken";
  gmail_url: string;
  suggestion: AiSuggestion | null;
  suggestion_error: string | null;
}

export interface ScanStarted {
  started: boolean;
}

/**
 * One flight leg, hotel stay, car rental, train or cruise. Its times are local wall-clock times at the place, never
 * converted: `start_local` is 2026-03-01T22:15 in `start_zone`, whatever zone the server or the viewer is in.
 */
export interface Segment {
  id: number;
  trip_id: number;
  kind: "flight" | "hotel" | "car" | "train" | "cruise";
  status: "confirmed" | "changed" | "cancelled";
  confirmation: string | null;
  provider: string | null;
  start_local: string;
  start_zone: string;
  end_local: string;
  end_zone: string;
  origin: string | null;
  destination: string | null;
  details: Record<string, string>;
  manage_url: string | null;
  source: "manual" | "email" | "import";
  booked_by: number | null;
  locked_fields: string[];
  check_times: boolean;
  travelers: Traveler[];
  itinerary: Port[];
  logo: string | null;
  links: SegmentLinks;
}

/**
 * A segment to add; `trip_id` leaves it to Waypoint to group it into a trip. A flight's zones come from its airports
 * unless given.
 */
export interface SegmentBody {
  kind: "flight" | "hotel" | "car" | "train" | "cruise";
  start_local: string;
  end_local: string;
  trip_id?: number | null;
  status?: "confirmed" | "changed" | "cancelled";
  confirmation?: string | null;
  provider?: string | null;
  start_zone?: string | null;
  end_zone?: string | null;
  origin?: string | null;
  destination?: string | null;
  details?: Record<string, string>;
  manage_url?: string | null;
  travelers?: TravelerBody[];
  itinerary?: Port[];
}

/** What to change on a segment: only the fields sent. The ones that end up different are locked. */
export interface SegmentEdit {
  kind?: "flight" | "hotel" | "car" | "train" | "cruise";
  status?: "confirmed" | "changed" | "cancelled";
  confirmation?: string | null;
  provider?: string | null;
  start_local?: string;
  start_zone?: string | null;
  end_local?: string;
  end_zone?: string | null;
  origin?: string | null;
  destination?: string | null;
  details?: Record<string, string>;
  manage_url?: string | null;
  travelers?: TravelerBody[];
  itinerary?: Port[];
}

export interface SegmentLinks {
  app: string | null;
  directions: string | null;
  call: string | null;
}

/** Who's signed in. Without sign-in configured (on your own machine), everyone is `local`. */
export interface SignedIn {
  name: string | null;
  email: string | null;
  sub?: string;
  local?: boolean;
}

export interface SplitBody {
  segment_ids: number[];
}

export interface Started {
  url: string;
}

export interface State {
  version: string;
  database: "sqlite" | "postgres";
  user: SignedIn | null;
  last_backup: string | null;
  review_count: number;
  person_id: number | null;
}

export interface Stats {
  years: number[];
  person: number | null;
  year: number | null;
  distance_unit: "mi" | "km";
  flights: StatsFlights;
  stays: StatsStays;
  cars: StatsCars;
  cruises: StatsCruises;
  places: StatsPlaces;
}

export interface StatsAirline {
  code: string | null;
  name: string;
  flights: number;
}

export interface StatsAirport {
  code: string;
  name: string;
  city: string | null;
  country: string | null;
  visits: number;
  latitude: number | null;
  longitude: number | null;
}

export interface StatsCars {
  days: number;
  companies: StatsNamed[];
}

export interface StatsCruises {
  count: number;
  nights: number;
  sea_days: number;
  ports: number;
  lines: StatsNamed[];
}

export interface StatsFlightRecord {
  origin: string;
  destination: string;
  distance_km: number;
  start_local: string;
  flight_number: string | null;
}

export interface StatsFlights {
  count: number;
  distance_km: number;
  air_seconds: number;
  airports: StatsAirport[];
  airlines: StatsAirline[];
  countries: StatsNamed[];
  routes: StatsRoute[];
  cabins: StatsNamed[];
  top_seat: string | null;
  seat_positions: StatsSeats;
  longest: StatsFlightRecord | null;
  shortest: StatsFlightRecord | null;
  most_visited_airport: string | null;
  busiest_month: string | null;
  times_around_earth: number;
  moon_fraction: number;
}

export interface StatsNamed {
  name: string;
  count: number;
}

export interface StatsPlace {
  name: string;
  first_visit: string;
  visits: number;
}

export interface StatsPlaces {
  countries: StatsPlace[];
  cities: StatsPlace[];
}

export interface StatsRoute {
  a: string;
  b: string;
  flights: number;
  distance_km: number | null;
  a_latitude: number | null;
  a_longitude: number | null;
  b_latitude: number | null;
  b_longitude: number | null;
}

export interface StatsSeats {
  window: number;
  aisle: number;
  middle: number;
  unknown: number;
}

export interface StatsStayPlace {
  name: string;
  stays: number;
  nights: number;
}

export interface StatsStayRecord {
  hotel: string | null;
  city: string | null;
  nights: number;
  start_local: string;
}

export interface StatsStays {
  nights: number;
  chains: StatsNamed[];
  cities: StatsNamed[];
  countries: StatsNamed[];
  count: number;
  average_nights: number;
  hotels: StatsStayPlace[];
  cities_by_nights: StatsStayPlace[];
  longest: StatsStayRecord | null;
  most_visited_hotel: StatsStayPlace | null;
  most_visited_city: StatsStayPlace | null;
  busiest_month: string | null;
}

export interface Traveler {
  id: number;
  person_id: number | null;
  name: string;
  seat: string | null;
}

export interface TravelerBody {
  person_id?: number | null;
  name?: string | null;
  seat?: string | null;
}

export interface Trip {
  id: number;
  name: string;
  start_date: string | null;
  end_date: string | null;
  destination: string | null;
  notes: string | null;
  auto: boolean;
  booked_by: number | null;
  segments: Segment[];
}

/** A trip made by hand, or what changes on one (a name, where it goes, notes; its dates come from its segments). */
export interface TripBody {
  name?: string;
  destination?: string | null;
  notes?: string | null;
  start_date?: string | null;
  end_date?: string | null;
}

export interface TripList {
  trips: Trip[];
}

/** Who a printed name is: a person in People, or a name to add as a guest. Send one. */
export interface WhoBody {
  person_id?: number;
  new_guest?: string;
}

/** A name on a booking that isn't matched to a person, with the segment it's on. */
export interface WhoIsThis {
  id: number;
  name: string;
  segment_id: number;
  trip_id: number;
  kind: "flight" | "hotel" | "car" | "train" | "cruise";
  provider: string | null;
  origin: string | null;
  destination: string | null;
  start_local: string;
  start_zone: string;
}

/** Each covered route ("METHOD /path", as in waypoint/server/routes.py): what it takes and what it answers. */
export interface Endpoints {
  "GET /api/ai": { body: never; reply: AiSettings };
  "POST /api/ai": { body: AiBody; reply: AiSettings };
  "POST /api/backup/inspect": { body: never; reply: BackupContents };
  "POST /api/restore": { body: never; reply: Restored };
  "GET /api/people": { body: never; reply: People };
  "POST /api/people": { body: PersonBody; reply: Person };
  "POST /api/people/{id}": { body: PersonBody; reply: Person };
  "DELETE /api/people/{id}": { body: never; reply: Ok };
  "POST /api/people/{id}/claim": { body: never; reply: Person };
  "GET /api/people/claim-suggestions": { body: never; reply: ClaimSuggestions };
  "POST /api/people/claim-suggestions/dismiss": { body: never; reply: Ok };
  "GET /api/trips": { body: never; reply: TripList };
  "POST /api/trips": { body: TripBody; reply: Trip };
  "GET /api/trips/{id}": { body: never; reply: Trip };
  "POST /api/trips/{id}": { body: TripBody; reply: Trip };
  "DELETE /api/trips/{id}": { body: never; reply: Ok };
  "POST /api/trips/{id}/merge": { body: MergeBody; reply: Trip };
  "POST /api/trips/{id}/split": { body: SplitBody; reply: Trip };
  "POST /api/segments": { body: SegmentBody; reply: Segment };
  "GET /api/segments/{id}": { body: never; reply: Segment };
  "POST /api/segments/{id}": { body: SegmentEdit; reply: Segment };
  "DELETE /api/segments/{id}": { body: never; reply: Ok };
  "GET /api/airports/{id}": { body: never; reply: Airport };
  "POST /api/import/preview": { body: never; reply: ImportPreview };
  "POST /api/import": { body: ImportBody; reply: Imported };
  "GET /api/stats": { body: never; reply: Stats };
  "GET /api/distance-unit": { body: never; reply: DistanceUnit };
  "POST /api/distance-unit": { body: DistanceUnitBody; reply: DistanceUnit };
  "GET /api/flight-status": { body: never; reply: FlightStatusList };
  "POST /api/flight-status/{id}": { body: never; reply: FlightStatusList };
  "GET /api/logodev": { body: never; reply: LogoDevStatus };
  "POST /api/logodev": { body: LogoDevBody; reply: LogoDevStatus };
  "POST /api/logodev/fetch": { body: never; reply: LogoDevFetch };
  "GET /api/loyalty": { body: never; reply: LoyaltyList };
  "POST /api/loyalty": { body: LoyaltyBody; reply: LoyaltyEntry };
  "POST /api/loyalty/{id}": { body: LoyaltyBody; reply: LoyaltyEntry };
  "DELETE /api/loyalty/{id}": { body: never; reply: Ok };
  "POST /api/loyalty/{id}/reveal": { body: never; reply: Revealed };
  "GET /api/mailboxes": { body: never; reply: MailboxList };
  "POST /api/mailboxes/connect": { body: never; reply: Started };
  "DELETE /api/mailboxes/{id}": { body: never; reply: Disconnected };
  "POST /api/mailboxes/{id}/scan": { body: never; reply: ScanStarted };
  "POST /api/mailboxes/{id}/reread": { body: never; reply: ScanStarted };
  "GET /api/reminders": { body: never; reply: Reminders };
  "POST /api/reminders": { body: RemindersBody; reply: Reminders };
  "POST /api/reminders/devices": { body: DeviceBody; reply: ReminderDevice };
  "DELETE /api/reminders/devices/{id}": { body: never; reply: Ok };
  "POST /api/feed": { body: never; reply: FeedMade };
  "DELETE /api/feed": { body: never; reply: Ok };
  "GET /api/review": { body: never; reply: Review };
  "POST /api/review/who/{id}": { body: WhoBody; reply: Matched };
  "POST /api/review/{id}/ignore": { body: never; reply: Ok };
  "GET /api/review/{id}/preview": { body: never; reply: Preview };
  "POST /api/review/{id}/suggest": { body: never; reply: Ok };
  "DELETE /api/review/{id}": { body: never; reply: Ok };
  "GET /api/mcp-settings": { body: never; reply: McpSettings };
  "POST /api/mcp-settings/writes": { body: McpWritesBody; reply: McpWritesBody };
  "DELETE /api/mcp-settings/connections/{id}": { body: never; reply: Ok };
  "GET /api/state": { body: never; reply: State };
}
